fn lock_pair<'a>(
    a: &'a Mutex<i64>,
    b: &'a Mutex<i64>,
) -> (MutexGuard<'a, i64>, MutexGuard<'a, i64>) {
    if (a as *const Mutex<i64>) < (b as *const Mutex<i64>) {
        let guard_a = a.lock().unwrap();
        let guard_b = b.lock().unwrap();
        (guard_a, guard_b)
    } else {
        let guard_b = b.lock().unwrap();
        let guard_a = a.lock().unwrap();
        (guard_a, guard_b)
    }
}

